// sort oldest to newest
if (!msg.payload || msg.payload.length === 0) return null;

msg.payload.sort((a, b) => a.timeCreated - b.timeCreated);
return msg;

const cursor_ts = msg.metadata.source.timestamp;
const utils = global.get("utils");
const connection = msg.metadata.connection_name;
const source = msg.metadata.source.identifier;

// Filter conditions
msg.payload = msg.payload.filter(entry => {
    if (entry.timeCreated <= cursor_ts) return false;
    if (entry.text && utils.is_bridge_message(entry.text)) return false;
    if (entry.loggedByFullName && utils.is_bridge_message(entry.loggedByFullName)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

// Update timestamp
global.set(
    `parat_bridge.connections.${connection}.clients.${source}.timestamp`,
    msg.payload[msg.payload.length - 1].timeCreated
);

return msg;

/**
 * Extracts publicly-accessible signed URLs from Rayvn entry text.
 *
 * Rayvn users generate signed URLs by right-clicking an attachment and
 * copying the link. These URLs are accessible without authentication.
 *
 * Found URLs are converted into synthetic file objects and appended to
 * msg.payload.files so the standard Classify files → Fetch Rayvn files
 * pipeline handles them identically to WaSOS → Rayvn file transfers.
 *
 * URLs are stripped from msg.payload.text so they do not appear in the
 * bridged WaSOS message.
 *
 * If no URLs are found, passes through unchanged.
 */
const url_pattern = /https?:\/\/\S+/gi;
const text        = msg.payload.text || "";
const matches     = [...text.matchAll(url_pattern)]
    .map(m => m[0].replace(/[.,;!?]+$/, ""));

if (matches.length === 0) return msg;

function guessType(url) {
    const path = url.split("?")[0].toLowerCase();
    if (path.endsWith(".jpg") || path.endsWith(".jpeg")) return "image/jpeg";
    if (path.endsWith(".png"))  return "image/png";
    if (path.endsWith(".gif"))  return "image/gif";
    if (path.endsWith(".webp")) return "image/webp";
    if (path.endsWith(".pdf"))  return "application/pdf";
    return "application/octet-stream";
}

const files = msg.payload.files || [];

for (const url of matches) {
    const raw_name = url.split("?")[0].split("/").pop() || "attachment";
    files.push({
        name: raw_name || "attachment",
        type: guessType(url),
        size: 0,
        url:  url
    });
}

msg.payload.files = files;

let new_text = text;
for (const url of matches) {
    new_text = new_text.split(url).join("");
}
msg.payload.text = new_text.trim();

return msg;
